import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "./supabase"

/**
 * Buying a domain, from the browser — FCS-120.
 * ============================================================================
 * Talks to the deployed `domain-buy` function as the signed-in customer. It never sends a price: the server works out
 * what is owed from the registrar's own figure, and this only ever asks for a name.
 *
 * The order is run by the SERVER (it registers the domain, finds the zone and wires it to the website); the pipeline
 * on screen only asks where it has got to. That is why a customer can pay at Stripe, close the tab, and come back to
 * find it finished.
 */

export async function buy(body) {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token
  if (!token) return { ok: false, status: 401, body: { message: "Log in to buy a domain." } }

  let res
  try {
    res = await fetch(apiUrl("domain-buy"), {
      method: "POST",
      headers: { "Content-Type": "application/json", apikey: SUPABASE_PUBLISHABLE_KEY, Authorization: `Bearer ${token}` },
      body: JSON.stringify(body),
    })
  } catch {
    return { ok: false, status: 0, body: { message: "Could not reach the server." } }
  }
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

/** Orders that are still moving, and orders that stopped somewhere they cannot move from on their own. */
export const MOVING = ["paid", "ordering", "registered", "wiring"]
export const STOPPED = ["refunded", "cancelled", "needs-attention"]

const pause = ms => new Promise(resolve => setTimeout(resolve, ms))

/**
 * Ask where an order has got to until it reaches one of the statuses in `reached`, or stops.
 *
 * Every ask also moves the order along on the server (the server lets only one run act at a time), so this is how a
 * customer who comes back later finishes their own purchase. An order that stopped with a wiring problem is retried
 * once at the start of a run: reaching here with it in that state means the customer pressed "Try again".
 */
export async function waitForOrder(orderId, reached, { tries = 70, ms = 4000, wait = pause } = {}) {
  let last = null
  for (let i = 0; i < tries; i += 1) {
    let res = await buy({ action: "status", orderId })
    if (i === 0 && res.ok && res.body.order?.status === "needs-attention" && res.body.order.canRetry) {
      res = await buy({ action: "retry", orderId })
    }
    if (res.ok && res.body.order) {
      last = res.body.order
      if (reached.includes(last.status)) return { ok: true, order: last }
      if (STOPPED.includes(last.status)) return { ok: false, order: last }
    } else if (res.status === 401 || res.status === 403 || res.status === 404) {
      return { ok: false, order: last, message: res.body.message || "We could not find that order." }
    }
    await wait(ms)
  }
  return { ok: false, order: last, timedOut: true }
}

/** What to tell somebody when waiting did not end well. */
export function whyNot(result) {
  if (result.order?.message && result.order.status !== "awaiting-payment") return result.order.message
  if (result.timedOut) return "It is taking longer than usual. Nothing is lost: come back to this page in a few minutes and it will carry on."
  return result.message || "We could not finish that just now."
}
