import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "./supabase"

/**
 * Domain search — FCS-078, FCS-080.
 * ============================================================================
 * Cloudflare Registrar, through our own `domain-search` Edge Function. It
 * used to point at contractor.wiki's Worker, which is not deployed anywhere
 * — so the search only worked while somebody had `wrangler dev` running on
 * their laptop, and everywhere else the pipeline fell back to made-up
 * prices. One hop now, always on.
 *
 * ── NO PRICE IS DEFINED IN THIS FILE, OR ANYWHERE NEAR IT ──────────────────
 * Every amount comes from the registrar. There is no fallback, no "from
 * $12", no placeholder, and nothing invents a plausible-looking number when
 * the service is down. That rule exists because it was broken once: a
 * simulated search offered google.com at $10.44 and was read as a real deal.
 * A wrong price next to a domain is not a cosmetic bug — somebody buys on it.
 */

/** Always available now: the search lives in our own project's functions. */
export const domainsConfigured = true

export const NOT_CONFIGURED =
  "Domain search is not switched on for this environment yet."

/** A keyword, cleaned to what a registrar will actually accept. */
export function cleanQuery(value) {
  return String(value || "")
    .toLowerCase()
    .trim()
    .replace(/^https?:\/\//, "")
    .replace(/[^a-z0-9.-]/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .slice(0, 63)
}

/**
 * Suggestions across extensions for a keyword.
 *
 * Returns `{ ok, domains, reason }` and never throws. A network failure is
 * NOT an empty result: telling somebody their perfectly good domain is taken
 * because a fetch failed is worse than telling them nothing.
 */
export async function searchDomains(query, { signal } = {}) {
  const q = cleanQuery(query)
  if (!q) return { ok: false, domains: [], reason: "Type a name to look for." }

  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token
  if (!token) {
    return {
      ok: false,
      domains: [],
      reason: "Log in to search for a domain.",
    }
  }

  let res
  try {
    res = await fetch(apiUrl("domain-search"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ q }),
      signal,
    })
  } catch (err) {
    if (err.name === "AbortError") return { ok: false, domains: [], reason: "" }
    return { ok: false, domains: [], reason: "Could not reach the domain service." }
  }

  const body = await res.json().catch(() => ({}))
  if (!res.ok) {
    return {
      ok: false,
      domains: [],
      reason: body.message || body.error || `The domain service answered ${res.status}.`,
    }
  }

  return {
    ok: true,
    domains: Array.isArray(body.domains) ? body.domains : [],
    // The free-domain offer, as the server saw it — FCS-094.
    offer: body.offer || null,
    reason: "",
  }
}

/** A price exactly as the registrar quoted it, in the registrar's currency. */
export function formatPrice(amount, currency = "USD") {
  const number = Number(amount)
  if (!Number.isFinite(number)) return ""
  try {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: String(currency || "USD").toUpperCase(),
    }).format(number)
  } catch {
    return `${number} ${currency}`
  }
}

/**
 * Why a name cannot be registered, in words rather than an error code.
 *
 * "domain_unavailable" on screen tells somebody nothing; "somebody already
 * has it" tells them to try another name, which is the only useful next step.
 */
export function unavailableReason(result) {
  const reason = String(result?.reason || "").toLowerCase()
  if (!reason) return "Not available"
  if (reason.includes("unavailable") || reason.includes("taken")) return "Already taken"
  if (reason.includes("premium")) return "Premium name — not sold here"
  if (reason.includes("reserved")) return "Reserved by the registry"
  if (reason.includes("invalid")) return "Not a valid name"
  if (reason.includes("unsupported") || reason.includes("tld")) return "This ending is not sold here"
  return "Not available"
}
