export function emptyState() {
  return {
    query: "",
    /** Everything the search returned, so a later step can re-read a price. */
    found: [],
    /** The name being bought. */
    domain: "",
    priceCents: 0,
    renewalCents: 0,
    /** The free-domain offer as the search reported it — FCS-094. */
    offer: null,
    /** Worked out by the `cover` step — see coverageFor. */
    coverage: null,
    orderId: "",
    zoneId: "",
    live: false,
  }
}

/**
 * What the customer pays, and what we absorb — FCS-080.
 *
 * Two outcomes and they are deliberately different words on screen:
 *
 *   covered  the name is standard-priced, so the first year is included and
 *            nothing is owed
 *   credit   the name costs more than standard, so the same amount comes off
 *            and the difference is owed
 *
 * The second is NOT described as "included": somebody who is paying twelve
 * dollars should be told they are paying twelve dollars, and an offer that
 * says "free" while taking money is the kind of thing people remember.
 */
export function coverageFor(priceCents, { creditOn = true } = {}) {
  const price = Math.max(0, Math.round(Number(priceCents) || 0))

  /* The offer is switched OFF by an administrator (FCS-094). Then there is no
     credit and no "included": the price is the price. Leaving the credit in
     while the labels said nothing was free would charge less than the screen
     promised, or promise less than it charged. */
  if (!creditOn) {
    return {
      kind: "full",
      priceCents: price,
      creditCents: 0,
      dueCents: price,
      summary: `You pay ${money(price)} for the first year.`,
    }
  }

  const covered = price > 0 && price <= STANDARD_MAX_CENTS

  if (covered) {
    return {
      kind: "covered",
      priceCents: price,
      creditCents: price,
      dueCents: 0,
      summary: "Included for the first year — nothing to pay now.",
    }
  }

  const credit = Math.min(CREDIT_CENTS, price)
  const due = Math.max(0, price - credit)

  /* Stripe will not take under 50 cents, so a few cents over the credit is absorbed rather than turned into a checkout that
     cannot open. The server applies the same rule (_shared/domain-order.ts), and refuses if the two ever disagree. */
  if (due > 0 && due < STRIPE_MIN_CENTS) {
    return {
      kind: "covered",
      priceCents: price,
      creditCents: price,
      dueCents: 0,
      summary: "Included for the first year — nothing to pay now.",
    }
  }
  return {
    kind: "credit",
    priceCents: price,
    creditCents: credit,
    dueCents: due,
    summary:
      due > 0
        ? `${money(credit)} comes off the first year. You pay ${money(due)}.`
        : "Covered in full by your first-year credit.",
  }
}

/**
 * What somebody would actually pay for a search result, in cents.
 *
 * The server sends `retail` (floored, renewal included) and that is what is
 * used. The fallback applies the same floor to the wholesale price so a result
 * from anywhere else still cannot show a price under it; it exists for that
 * and for nothing else.
 */
export function retailOf(domain) {
  if (domain?.retail && Number.isFinite(domain.retail.registrationCents)) return domain.retail
  const cost = Math.round(Number(domain?.pricing?.registration_cost) * 100)
  const renewal = Math.round(Number(domain?.pricing?.renewal_cost) * 100)
  if (!Number.isFinite(cost)) return null
  return {
    registrationCents: Math.max(cost, MIN_PRICE_CENTS),
    renewalCents: Math.max(Number.isFinite(renewal) ? renewal : cost, MIN_PRICE_CENTS),
    floored: cost < MIN_PRICE_CENTS,
  }
}

export function money(cents) {
  return formatPrice((Number(cents) || 0) / 100, CURRENCY)
}

/* ── The transports ──────────────────────────────────────────────────────
   Each returns { success, step, data, log, error }. Nothing throws: a failed
   step is a result, because the UI has to render it either way. */

const ok = (step, data, log) => ({ success: true, step, data: data || {}, log: log || [] })
const bad = (step, error, log) => ({ success: false, step, data: {}, log: log || [], error })

/**
 * Realistic answers with nothing behind them, for walking the flow.
 *
 * Every screen this produces is marked as a rehearsal by the caller — see
 * DomainPipeline, which will not let a simulated run claim a domain is live.
 */
export const simulate = {
  id: "simulate",
  label: "Rehearsal",

  /**
   * The REAL search, even in a rehearsal.
   *
   * This used to invent a set — `<keyword>.com` at $10.44, `<keyword>.co` at
   * $28.00 — when no backend answered. Searching "google" therefore offered
   * google.com for $10.44, and it was read, entirely reasonably, as a real
   * deal worth buying. That is as bad as this product gets: a made-up price
   * beside a real domain name, indistinguishable from a quote.
   *
   * A rehearsal is now only about not SPENDING. What is available and what
   * it costs always comes from the registrar, so every number on screen is
   * one somebody could act on — and when the registrar cannot be reached the
   * step fails and says so, which is the honest answer.
   */
  async search(state) {
    const result = await searchDomains(state.query)
    if (!result.ok) {
      return bad("search", result.reason || "Could not reach the domain service.")
    }
    if (result.domains.length === 0) {
      return ok("search", { found: [], offer: result.offer }, ["Nothing came back for that."])
    }
    return ok("search", { found: result.domains, offer: result.offer }, [
      `${result.domains.length} ${result.domains.length === 1 ? "name" : "names"} came back, priced by the registrar.`,
    ])
  },

  async price(state) {
    const match = state.found.find(d => d.name === state.domain)
    const retail = retailOf(match)
    if (!retail) return bad("price", "No price came back for that name.")
    return ok(
      "price",
      { priceCents: retail.registrationCents, renewalCents: retail.renewalCents },
      [`${state.domain} — ${money(retail.registrationCents)} for the first year`]
    )
  },

  async cover(state) {
    const coverage = coverageFor(state.priceCents, { creditOn: state.offer?.enabled !== false })
    return ok("cover", { coverage }, [coverage.summary])
  },

  async checkout(state) {
    if (!state.coverage || state.coverage.dueCents === 0) {
      return ok("checkout", {}, ["Nothing owed, so no payment was opened."])
    }
    return ok("checkout", {}, [`Rehearsal: would take ${money(state.coverage.dueCents)}.`])
  },

  async order(state) {
    return ok("order", { orderId: `sim_${Date.now().toString(36)}` }, [
      `Rehearsal: ${state.domain} would be registered now.`,
    ])
  },

  async zone(state) {
    return ok("zone", { zoneId: `sim_zone_${Date.now().toString(36)}` }, [
      `Rehearsal: zone created for ${state.domain}.`,
    ])
  },

  async records() {
    return ok("records", {}, ["Rehearsal: A and CNAME records written."])
  },

  async attach(state) {
    return ok("attach", {}, [`Rehearsal: host told to answer for ${state.domain}.`])
  },

  async ssl() {
    return ok("ssl", {}, ["Rehearsal: certificate requested."])
  },

  async verify(state) {
    return ok("verify", { live: false }, [
      `Rehearsal only — ${state.domain} was not bought and is not live.`,
    ])
  },
}

/**
 * The real thing, against the Worker that holds the registrar token.
 *
 * Deliberately incomplete: `search`, `price` and `cover` are real because the
 * search endpoint exists. Everything that spends money or changes DNS refuses
 * until the endpoints behind it are built, rather than returning a success
 * nobody can cash. A pipeline that reports "registered" without registering
 * is worse than one that stops.
 */
export const live = {
  id: "live",
  label: "Live",

  /**
   * The real search, which fails rather than inventing.
   *
   * NOT simulate.search: that one makes up a plausible set of names and
   * prices when nothing answers, which is right for a rehearsal and wrong
   * here to the point of being dangerous. A made-up price in live mode is a
   * price somebody decides to buy on.
   */
  async search(state) {
    if (!domainsConfigured) {
      return bad("search", NOT_CONFIGURED)
    }
    const result = await searchDomains(state.query)
    if (!result.ok) {
      return bad("search", result.reason || "Could not reach the domain service.")
    }
    if (result.domains.length === 0) {
      return ok("search", { found: [] }, ["Nothing came back for that."])
    }
    return ok("search", { found: result.domains }, [
      `${result.domains.length} ${result.domains.length === 1 ? "name" : "names"} came back.`,
    ])
  },

  price: simulate.price,

  cover: simulate.cover,

  /* Opens the order. Nothing owed: the server runs it at once. Something owed: the customer is sent to Stripe, and the
     server carries on when Stripe says the payment went through (the signed webhook), not when this page does. */
  async checkout(state) {
    /* The browser says which name and which figure it SHOWED. The server works out its own figure from the registrar's price and
       charges that; if the two differ it refuses and says so, so a customer never pays an amount they were not looking at. */
    const res = await buy({ action: "start", domain: state.domain, origin: window.location.origin, expectDueCents: state.coverage?.dueCents })
    if (res.status === 409 && res.body.code === "price-changed") {
      return bad("checkout", `The price has changed to ${money(res.body.dueCents)}. Nothing has been charged. Start over to see it.`)
    }
    if (!res.ok) return bad("checkout", res.body.message || "We could not start the order. Nothing has been charged.")
    if (res.body.url) {
      window.location.assign(res.body.url)
      return ok("checkout", { orderId: res.body.orderId, redirected: true }, ["Taking you to Stripe to pay…"])
    }
    const order = res.body.order
    return ok("checkout", { orderId: order.id }, [state.coverage?.dueCents ? "Paid." : "Nothing owed, so no payment was needed."])
  },

  /* The steps below do not DO anything: the server registers, finds the zone, writes the records, sets the domain on the
     site and checks it answers. Each one waits until the order reaches the point that step stands for. */
  async order(state) {
    if (state.redirected) return new Promise(() => {}) // the page is on its way to Stripe
    const r = await waitForOrder(state.orderId, ["registered", "wiring", "live", "sandbox-done"])
    if (!r.ok) return bad("order", whyNot(r))
    return ok("order", {}, [r.order.mode === "sandbox" ? "Test registration (sandbox): nothing real was bought." : `${state.domain} is registered.`])
  },

  async zone(state) {
    const r = await waitForOrder(state.orderId, ["wiring", "live", "sandbox-done"])
    if (!r.ok) return bad("zone", whyNot(r))
    return ok("zone", {}, [r.order.status === "sandbox-done" ? "Sandbox: no zone was made." : "The domain's DNS zone is ready."])
  },

  async records(state) {
    const r = await waitForOrder(state.orderId, ["live", "sandbox-done"])
    if (!r.ok) return bad("records", whyNot(r))
    return ok("records", {}, [r.order.status === "sandbox-done" ? "Sandbox: no records were written." : "The DNS records point at your website."])
  },

  async attach(state) {
    const r = await waitForOrder(state.orderId, ["live", "sandbox-done"])
    if (!r.ok) return bad("attach", whyNot(r))
    return ok("attach", {}, [r.order.status === "sandbox-done" ? "Sandbox: nothing was attached." : "Your website now answers for the domain."])
  },

  async ssl(state) {
    const r = await waitForOrder(state.orderId, ["live", "sandbox-done"])
    if (!r.ok) return bad("ssl", whyNot(r))
    return ok("ssl", {}, [r.order.status === "sandbox-done" ? "Sandbox: no certificate was needed." : "HTTPS is switched on."])
  },

  async verify(state) {
    const r = await waitForOrder(state.orderId, ["live", "sandbox-done"])
    if (!r.ok) return bad("verify", whyNot(r))
    const live = r.order.status === "live"
    return ok("verify", { live }, [live ? `${state.domain} shows your website.` : "Sandbox only — no real domain was bought and nothing is live."])
  },
}

/** Runs one step through a transport and folds its data into the state. */
export async function runStep(transport, step, state) {
  const fn = transport[step.id]
  if (typeof fn !== "function") {
    return bad(step.id, `This transport has no "${step.id}" step.`)
  }
  try {
    return await fn(state)
  } catch (err) {
    return bad(step.id, err?.message || "That step failed.")
  }
}
